import{_ as a,o,c as r,ae as t}from"./chunks/framework.YL6nI5ZP.js";const u=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"reference/08-glossary.md","filePath":"reference/08-glossary.md"}'),i={name:"reference/08-glossary.md"};function n(s,e,l,d,h,c){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Alphabetical list of the project&#39;s terms and their meanings. Merges the engineering-manual glossary with the domain glossary of <code>CONTEXT.md</code>; where the domain glossary defines a term in Spanish, the Spanish term is kept in parentheses.</p><h2 id="_1d-2d" tabindex="-1">1D / 2D <a class="header-anchor" href="#_1d-2d" aria-label="Permalink to &quot;1D / 2D&quot;">​</a></h2><p>Pipe/network model vs. overland surface-routing mesh model.</p><h2 id="cd-coupling" tabindex="-1">CD / coupling <a class="header-anchor" href="#cd-coupling" aria-label="Permalink to &quot;CD / coupling&quot;">​</a></h2><p>Flow coefficient / 1D↔2D exchange coefficient (default 0.65).</p><h2 id="cdt" tabindex="-1">CDT <a class="header-anchor" href="#cdt" aria-label="Permalink to &quot;CDT&quot;">​</a></h2><p>Constrained Delaunay Triangulation.</p><h2 id="cfl" tabindex="-1">CFL <a class="header-anchor" href="#cfl" aria-label="Permalink to &quot;CFL&quot;">​</a></h2><p>Courant–Friedrichs–Lewy stability condition.</p><h2 id="cplf-cpls" tabindex="-1">cplF / cplS <a class="header-anchor" href="#cplf-cpls" aria-label="Permalink to &quot;cplF / cplS&quot;">​</a></h2><p>Coupling float/state buffers between the WASM 1D engine and the GPU 2D marcher.</p><h2 id="engineclient" tabindex="-1">EngineClient <a class="header-anchor" href="#engineclient" aria-label="Permalink to &quot;EngineClient&quot;">​</a></h2><p>Seam of the frontend between the UI and the engine, with two switchable implementations: local (WASM in the browser) and remote (via API). <em>Avoid</em>: engine module, engine wrapper.</p><h2 id="engine-worker-pool-pool-de-workers-del-motor" tabindex="-1">Engine worker pool (Pool de workers del motor) <a class="header-anchor" href="#engine-worker-pool-pool-de-workers-del-motor" aria-label="Permalink to &quot;Engine worker pool (Pool de workers del motor)&quot;">​</a></h2><p>Set of native processes on the server that execute runs, one per core, taking work from a queue. <em>Avoid</em>: thread, except OpenMP inside a worker.</p><h2 id="feature-state" tabindex="-1">feature-state <a class="header-anchor" href="#feature-state" aria-label="Permalink to &quot;feature-state&quot;">​</a></h2><p>Mapbox GL JS per-feature mutable styling state.</p><h2 id="indexed-mesh" tabindex="-1">Indexed mesh <a class="header-anchor" href="#indexed-mesh" aria-label="Permalink to &quot;Indexed mesh&quot;">​</a></h2><p><code>Net.mesh2DIndexed</code>: the canonical Triangle-engine mesh output.</p><h2 id="inp" tabindex="-1">INP <a class="header-anchor" href="#inp" aria-label="Permalink to &quot;INP&quot;">​</a></h2><p>SWMM input text file (<code>.inp</code>); the model serialization consumed by the engine.</p><h2 id="local-mode-api-mode-modo-local-modo-api" tabindex="-1">Local mode / API mode (Modo local / Modo API) <a class="header-anchor" href="#local-mode-api-mode-modo-local-modo-api" aria-label="Permalink to &quot;Local mode / API mode (Modo local / Modo API)&quot;">​</a></h2><p>The two execution paths of the EngineClient: WASM engine in the browser (offline) vs engine on the server via API (default).</p><h2 id="lts" tabindex="-1">LTS <a class="header-anchor" href="#lts" aria-label="Permalink to &quot;LTS&quot;">​</a></h2><p>Local Time Stepping — the 2D solver&#39;s tiered substep scheme.</p><h2 id="m0–m5" tabindex="-1">M0–M5 <a class="header-anchor" href="#m0–m5" aria-label="Permalink to &quot;M0–M5&quot;">​</a></h2><p>WebGPU milestone phases in <code>WEBGPU_PLAN.md</code>.</p><h2 id="memfs" tabindex="-1">MEMFS <a class="header-anchor" href="#memfs" aria-label="Permalink to &quot;MEMFS&quot;">​</a></h2><p>Emscripten&#39;s in-memory virtual filesystem (<code>.inp</code>/<code>.rpt</code>/<code>.out</code> live there).</p><h2 id="openswmm" tabindex="-1">OpenSWMM <a class="header-anchor" href="#openswmm" aria-label="Permalink to &quot;OpenSWMM&quot;">​</a></h2><p>The C++20 re-implementation used here (HydroCouple); MIT-licensed.</p><h2 id="pslg" tabindex="-1">PSLG <a class="header-anchor" href="#pslg" aria-label="Permalink to &quot;PSLG&quot;">​</a></h2><p>Planar Straight-Line Graph — the constrained triangulation input to Triangle.</p><h2 id="pslc" tabindex="-1">PSLC <a class="header-anchor" href="#pslc" aria-label="Permalink to &quot;PSLC&quot;">​</a></h2><p>Planar Straight-Line <strong>Cell</strong> graph (the mesh2dPslg module&#39;s term).</p><h2 id="rpt-out" tabindex="-1">RPT / OUT <a class="header-anchor" href="#rpt-out" aria-label="Permalink to &quot;RPT / OUT&quot;">​</a></h2><p>Engine text report / binary results files.</p><h2 id="run-corrida" tabindex="-1">Run (Corrida) <a class="header-anchor" href="#run-corrida" aria-label="Permalink to &quot;Run (Corrida)&quot;">​</a></h2><p>A complete execution of a simulation model (1D+2D) with lifecycle: queued → running → finished (or failed). It is identified by an ID and is what the user triggers with Run. <em>Avoid</em>: job, run, simulation (the simulation is the modeled phenomenon; the run is the execution).</p><h2 id="run-progress-progreso-de-corrida" tabindex="-1">Run progress (Progreso de corrida) <a class="header-anchor" href="#run-progress-progreso-de-corrida" aria-label="Permalink to &quot;Run progress (Progreso de corrida)&quot;">​</a></h2><p>Live state of a run: sim-time reached, fraction of the total, phase. Queryable by ID; it is what paints the Run Status UI.</p><h2 id="run-results-resultados-de-corrida" tabindex="-1">Run results (Resultados de corrida) <a class="header-anchor" href="#run-results-resultados-de-corrida" aria-label="Permalink to &quot;Run results (Resultados de corrida)&quot;">​</a></h2><p>Finished product of a run: JSON tables (1D series per node/link/subcatchment and 2D frames captured live) plus the binary <code>.out</code> and <code>.rpt</code> files for export.</p><h2 id="swmm" tabindex="-1">SWMM <a class="header-anchor" href="#swmm" aria-label="Permalink to &quot;SWMM&quot;">​</a></h2><p>EPA Storm Water Management Model; the hydrology/hydraulics reference.</p><h2 id="system-status-estado-del-sistema" tabindex="-1">System status (Estado del sistema) <a class="header-anchor" href="#system-status-estado-del-sistema" aria-label="Permalink to &quot;System status (Estado del sistema)&quot;">​</a></h2><p>Aggregated health endpoint: app version, worker pool state, active runs. Queryable for scripts, CI and debugging. <em>Avoid</em>: health endpoint, run status (that is the progress of a specific run).</p><h2 id="triangle" tabindex="-1">Triangle <a class="header-anchor" href="#triangle" aria-label="Permalink to &quot;Triangle&quot;">​</a></h2><p>Shewchuk&#39;s Delaunay triangulator; here compiled to WASM (<code>triangle-wasm</code>).</p><h2 id="wasm-emscripten" tabindex="-1">WASM / Emscripten <a class="header-anchor" href="#wasm-emscripten" aria-label="Permalink to &quot;WASM / Emscripten&quot;">​</a></h2><p>WebAssembly + the LLVM toolchain that compiles C++ to it.</p>',52)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
